import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_transpose_conv_ext = None


def _get_transpose_conv_ext():
    global _transpose_conv_ext
    if _transpose_conv_ext is not None:
        return _transpose_conv_ext

    cpp_source = r"""
#include <torch/extension.h>

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &conv_transpose2d_cuda, "Grouped 2D transposed convolution forward (CUDA)");
}
"""

    cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <c10/cuda/CUDAException.h>
#include <cuda_runtime.h>

__device__ __forceinline__ int64_t floor_div_int64(int64_t a, int64_t b) {
    int64_t q = a / b;
    int64_t r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) {
        --q;
    }
    return q;
}

template <typename scalar_t>
__global__ void transposed_conv2d_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t n,
    int64_t in_channels,
    int64_t in_height,
    int64_t in_width,
    int64_t out_channels,
    int64_t out_height,
    int64_t out_width,
    int64_t kernel_height,
    int64_t kernel_width,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups,
    int64_t has_bias) {
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 8;
    constexpr int TILE_OC = 4;

    const int tid = threadIdx.x;
    const int tx = tid & 7;
    const int ty = (tid >> 3) & 7;
    const int oc_tile_local = tid >> 6;

    const int64_t spatial_tiles_x = (out_width + TILE_W - 1) / TILE_W;
    const int64_t spatial_tile = blockIdx.x;
    const int64_t tile_ox = spatial_tile % spatial_tiles_x;
    const int64_t tile_oy = spatial_tile / spatial_tiles_x;
    const int64_t ox0 = tile_ox * TILE_W;
    const int64_t oy0 = tile_oy * TILE_H;

    const int64_t oc_tile_base = static_cast<int64_t>(blockIdx.y) * TILE_OC;
    const int64_t group = blockIdx.z % groups;
    const int64_t batch = blockIdx.z / groups;
    const int64_t out_channels_per_group = out_channels / groups;
    const int64_t in_channels_per_group = in_channels / groups;

    const int64_t y_raw_min = floor_div_int64(
        oy0 + padding_h - (kernel_height - 1) * dilation_h, stride_h);
    const int64_t y_raw_max = floor_div_int64(
        oy0 + TILE_H - 1 + padding_h, stride_h);
    const int64_t x_raw_min = floor_div_int64(
        ox0 + padding_w - (kernel_width - 1) * dilation_w, stride_w);
    const int64_t x_raw_max = floor_div_int64(
        ox0 + TILE_W - 1 + padding_w, stride_w);

    const int64_t iy_min = y_raw_min > 0 ? y_raw_min : 0;
    const int64_t iy_max = y_raw_max < in_height - 1 ? y_raw_max : in_height - 1;
    const int64_t ix_min = x_raw_min > 0 ? x_raw_min : 0;
    const int64_t ix_max = x_raw_max < in_width - 1 ? x_raw_max : in_width - 1;
    const int64_t sm_h = iy_max >= iy_min ? iy_max - iy_min + 1 : 0;
    const int64_t sm_w = ix_max >= ix_min ? ix_max - ix_min + 1 : 0;

    extern __shared__ unsigned char shared_raw[];
    scalar_t* shared_x = reinterpret_cast<scalar_t*>(shared_raw);
    scalar_t* shared_w = shared_x + in_channels_per_group * sm_h * sm_w;

    const int64_t x_elements = in_channels_per_group * sm_h * sm_w;
    if (sm_h > 0 && sm_w > 0) {
        for (int64_t i = tid; i < x_elements; i += blockDim.x) {
            const int64_t ix_local = i % sm_w;
            const int64_t tmp0 = i / sm_w;
            const int64_t iy_local = tmp0 % sm_h;
            const int64_t ic_local = tmp0 / sm_h;
            const int64_t ix = ix_min + ix_local;
            const int64_t iy = iy_min + iy_local;
            const int64_t ic = group * in_channels_per_group + ic_local;
            shared_x[i] = x[((batch * in_channels + ic) * in_height + iy) * in_width + ix];
        }
    }

    const int64_t w_elements = TILE_OC * in_channels_per_group * kernel_height * kernel_width;
    for (int64_t i = tid; i < w_elements; i += blockDim.x) {
        const int64_t kx = i % kernel_width;
        const int64_t tmp0 = i / kernel_width;
        const int64_t ky = tmp0 % kernel_height;
        const int64_t tmp1 = tmp0 / kernel_height;
        const int64_t ic_local = tmp1 % in_channels_per_group;
        const int64_t oc_local = tmp1 / in_channels_per_group;
        const int64_t oc_in_group = oc_tile_base + oc_local;
        if (oc_in_group < out_channels_per_group) {
            const int64_t ic = group * in_channels_per_group + ic_local;
            const int64_t weight_idx =
                (((ic * out_channels_per_group + oc_in_group) * kernel_height + ky) *
                 kernel_width + kx);
            shared_w[i] = weight[weight_idx];
        } else {
            shared_w[i] = scalar_t(0);
        }
    }
    __syncthreads();

    const int64_t oy = oy0 + ty;
    const int64_t ox = ox0 + tx;
    const int64_t oc_in_group = oc_tile_base + oc_tile_local;
    if (oy >= out_height || ox >= out_width || oc_in_group >= out_channels_per_group) {
        return;
    }

    const int64_t oc = group * out_channels_per_group + oc_in_group;
    scalar_t acc = has_bias ? bias[oc] : scalar_t(0);

    for (int64_t ky = 0; ky < kernel_height; ++ky) {
        const int64_t y_num = oy + padding_h - ky * dilation_h;
        if (y_num < 0 || y_num % stride_h != 0) {
            continue;
        }
        const int64_t iy = y_num / stride_h;
        if (iy < iy_min || iy > iy_max) {
            continue;
        }
        for (int64_t kx = 0; kx < kernel_width; ++kx) {
            const int64_t x_num = ox + padding_w - kx * dilation_w;
            if (x_num < 0 || x_num % stride_w != 0) {
                continue;
            }
            const int64_t ix = x_num / stride_w;
            if (ix < ix_min || ix > ix_max) {
                continue;
            }
            const int64_t iy_local = iy - iy_min;
            const int64_t ix_local = ix - ix_min;
            for (int64_t ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
                const int64_t x_idx = (ic_local * sm_h + iy_local) * sm_w + ix_local;
                const int64_t w_idx =
                    ((oc_tile_local * in_channels_per_group + ic_local) * kernel_height + ky) *
                    kernel_width + kx;
                acc += shared_x[x_idx] * shared_w[w_idx];
            }
        }
    }

    const int64_t output_idx =
        ((batch * out_channels + oc) * out_height + oy) * out_width + ox;
    output[output_idx] = acc;
}

torch::Tensor conv_transpose2d_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    int64_t stride_h,
    int64_t stride_w,
    int64_t padding_h,
    int64_t padding_w,
    int64_t dilation_h,
    int64_t dilation_w,
    int64_t groups) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "Weight must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(weight.is_contiguous(), "Weight must be contiguous");
    TORCH_CHECK(
        bias.numel() == 0 || bias.is_cuda(),
        "Bias must be CUDA or empty");
    TORCH_CHECK(
        bias.numel() == 0 || bias.is_contiguous(),
        "Bias must be contiguous");

    TORCH_CHECK(x.dim() == 4, "Input must have shape [N, C, H, W]");
    TORCH_CHECK(weight.dim() == 4, "Weight must have shape [C, O/G, KH, KW]");
    TORCH_CHECK(groups > 0, "groups must be positive");

    const int64_t batch = x.size(0);
    const int64_t in_channels = x.size(1);
    const int64_t in_height = x.size(2);
    const int64_t in_width = x.size(3);

    const int64_t kernel_height = weight.size(2);
    const int64_t kernel_width = weight.size(3);
    const int64_t out_channels_per_group = weight.size(1);
    const int64_t out_channels = out_channels_per_group * groups;

     TORCH_CHECK(stride_h > 0 && stride_w > 0, "Stride must be positive");
     TORCH_CHECK(
         padding_h >= 0 && padding_w >= 0,
         "Padding must be nonnegative");
     TORCH_CHECK(
         dilation_h > 0 && dilation_w > 0,
         "Dilation must be positive");
     TORCH_CHECK(
         out_channels_per_group > 0,
         "Weight must have a positive output-channel dimension");
     TORCH_CHECK(
         bias.numel() == 0 || bias.numel() == out_channels,
         "Bias must have size equal to the number of output channels");
    TORCH_CHECK(in_channels % groups == 0, "Invalid input channel grouping");
    TORCH_CHECK(
        weight.size(0) == in_channels,
        "Weight input-channel dimension mismatch");

     TORCH_CHECK(
         x.scalar_type() == weight.scalar_type(),
         "Input and weight must have the same dtype");
     TORCH_CHECK(
         bias.numel() == 0 || bias.scalar_type() == x.scalar_type(),
         "Input and bias must have the same dtype");
    const int64_t out_height =
        (in_height - 1) * stride_h -
        2 * padding_h +
        dilation_h * (kernel_height - 1) +
        1;

    const int64_t out_width =
        (in_width - 1) * stride_w -
        2 * padding_w +
        dilation_w * (kernel_width - 1) +
        1;

    TORCH_CHECK(out_height >= 0 && out_width >= 0, "Invalid output size");

    c10::cuda::CUDAGuard device_guard(x.device());

    auto output = torch::empty(
        {batch, out_channels, out_height, out_width},
        x.options());


     if (batch == 0 || out_height == 0 || out_width == 0) {
         return output;
     }
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 8;
    constexpr int TILE_OC = 4;
    constexpr int threads = TILE_H * TILE_W * TILE_OC;
    const int64_t spatial_tiles_x = (out_width + TILE_W - 1) / TILE_W;
    const int64_t spatial_tiles_y = (out_height + TILE_H - 1) / TILE_H;
    const int64_t spatial_tiles = spatial_tiles_x * spatial_tiles_y;
    const int64_t in_channels_per_group = in_channels / groups;

    const int64_t max_sm_h =
        (TILE_H - 1 + 2 * padding_h + dilation_h * (kernel_height - 1)) / stride_h + 2;
    const int64_t max_sm_w =
        (TILE_W - 1 + 2 * padding_w + dilation_w * (kernel_width - 1)) / stride_w + 2;
    const size_t shared_bytes = static_cast<size_t>(
        (in_channels_per_group * max_sm_h * max_sm_w +
         TILE_OC * in_channels_per_group * kernel_height * kernel_width) *
        x.element_size());

    const dim3 grid(
        static_cast<unsigned int>(spatial_tiles),
        static_cast<unsigned int>((out_channels_per_group + TILE_OC - 1) / TILE_OC),
        static_cast<unsigned int>(batch * groups));

    const bool has_bias = bias.numel() != 0;

    AT_DISPATCH_FLOATING_TYPES(
        x.scalar_type(),
        "conv_transpose2d_cuda",
        [&] {
            const scalar_t* bias_ptr =
                has_bias ? bias.data_ptr<scalar_t>() : nullptr;

            auto stream =
                at::cuda::getCurrentCUDAStream(x.device().index()).stream();
            transposed_conv2d_kernel<scalar_t>
                <<<grid, threads, shared_bytes, stream>>> (
                    x.data_ptr<scalar_t>(),
                    weight.data_ptr<scalar_t>(),
                    bias_ptr,
                    output.data_ptr<scalar_t>(),
                    batch,
                    in_channels,
                    in_height,
                    in_width,
                    out_channels,
                    out_height,
                    out_width,
                    kernel_height,
                    kernel_width,
                    stride_h,
                    stride_w,
                    padding_h,
                    padding_w,
                    dilation_h,
                    dilation_w,
                    groups,
                    has_bias ? 1 : 0);
        });

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
