    _transpose_conv_ext = load_inline(
        name="custom_grouped_transpose_conv2d",
        cpp_sources=cpp_source,
        cuda_sources=cuda_source,
        functions=None,
        extra_cflags=["-O3", "-std=c++17"],
        extra_cuda_cflags=["-O3", "-std=c++17"],
        with_cuda=True,
        verbose=False,
    )
    return _transpose_conv_ext


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()

        self.conv_transpose2d = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=groups,
            bias=bias,
        )

        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        _get_transpose_conv_ext()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA input")

        x = x.contiguous()
        weight = self.conv_transpose2d.weight.contiguous()

        if self.conv_transpose2d.bias is None:
            bias = x.new_empty((0,))
        else:
            bias = self.conv_transpose2d.bias.contiguous()

        return _transpose_conv_ext.forward(
            x,
            weight,
            bias,
            int(self.stride[0]),
            int(self.stride[1]),
            int(self.padding[0]),
            int(self.padding[1]),
            int(self.dilation[0]),
            int(self.dilation[1]),
            int(self.groups),
        )

